export const databaseStats = {
  totalPhones: 853,
  totalBrands: 40,
  categories: ["Flagship", "Premium", "Mid-Range", "Budget", "Gaming", "Rugged", "Foldable"],
};
// ─── Helpers ────────────────────────────────────────────────

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

// Maps database brand values to the slugs used in featuredBrands / URLs
const brandToSlug: Record<string, string> = {
  "nokia (hmd)": "nokia",
  "cmf by nothing": "cmf",
  redmi: "xiaomi",
};

// `phones` is the same data as phoneDatabase, but with brand normalised to the URL slug
export const phones: Phone[] = phoneDatabase.map((p) => ({
  ...p,
  brand: brandToSlug[p.brand.toLowerCase()] ?? p.brand.toLowerCase(),
}));

export function getPhonesByBrand(slug: string): Phone[] {
  return phones.filter((p) => p.brand === slug.toLowerCase());
}

export function getPhone(brandSlug: string, phoneSlug: string): Phone | undefined {
  return phones.find(
    (p) => p.brand === brandSlug.toLowerCase() && slugify(p.name) === phoneSlug
  );
}
